import { useMemo } from 'react';

import type { TocGroup, TocItem, TocSubItem } from 'components/TableOfContents';
import { useAssetHost } from 'config/api';

import {
  EXPORT_COUNTRIES,
  getCountrySlideId,
  PAGE_LAYOUT,
  pageSections,
  TOC_COUNTRY_CODES,
  UNIFIED_GLOBAL_SLIDES,
} from '../../constants';

const GoldDot = () => (
  <span
    style={{
      width: 12,
      height: 12,
      borderRadius: '50%',
      background: '#F0AB00',
      display: 'inline-block',
      flexShrink: 0,
    }}
  />
);

const QTD_OVERVIEW_COUNT = UNIFIED_GLOBAL_SLIDES.filter(
  (s) =>
    s.type === 'evolution' ||
    s.type === 'by-country' ||
    s.type === 'contribution',
).length;

const QTD_SLIDE_COUNT = UNIFIED_GLOBAL_SLIDES.length;

const YTD_SLIDE_COUNT = UNIFIED_GLOBAL_SLIDES.filter(
  (s) => s.type !== 'evolution',
).length;

export const useTocGroups = (
  quarterYearFull: string,
  fiscalYear: string,
): TocGroup[] => {
  const assetHost = useAssetHost();

  return useMemo(() => {
    const qtdLabel = quarterYearFull || 'QTD';
    const ytdLabel = fiscalYear ? `YTD ${fiscalYear}` : 'YTD';
    const resultsDescription =
      'Country, Megabrands, Price Tiers and Global Brands';

    const globalPage = PAGE_LAYOUT.FIXED_PAGES_BEFORE_GLOBAL + 1;
    const qtdResultsPage = globalPage + QTD_OVERVIEW_COUNT;
    const ytdResultsPage = globalPage + QTD_SLIDE_COUNT;
    const countryStartPage =
      globalPage + QTD_SLIDE_COUNT + 1 + YTD_SLIDE_COUNT + 1;

    const stackedGroup: TocGroup = {
      layout: 'stacked',
      items: [
        {
          title: 'Global Power Book',
          page: globalPage,
          slideId: pageSections.totalAbiPowerEvolution,
          icon: <GoldDot />,
        },
        {
          title: `${qtdLabel} Results:`,
          description: resultsDescription,
          page: qtdResultsPage,
          slideId: pageSections.segmentsCover,
        },
        {
          title: `${ytdLabel} Results:`,
          description: resultsDescription,
          page: ytdResultsPage,
          slideId: pageSections.coverYtdResults,
        },
      ],
    };

    let currentPage = countryStartPage;
    const countryPageMap = new Map<
      string,
      { cover: number; qtd: number; ytd: number }
    >();

    EXPORT_COUNTRIES.forEach((c) => {
      const coverPage = currentPage;
      const slidesPerCountry = c.hasFullSlides
        ? PAGE_LAYOUT.SLIDES_PER_FULL_COUNTRY
        : PAGE_LAYOUT.SLIDES_PER_SIMPLE_COUNTRY;
      const qtdOffset = c.hasFullSlides
        ? PAGE_LAYOUT.QTD_OFFSET_FULL
        : PAGE_LAYOUT.QTD_OFFSET_SIMPLE;
      const ytdOffset = c.hasFullSlides
        ? PAGE_LAYOUT.YTD_OFFSET_FULL
        : PAGE_LAYOUT.YTD_OFFSET_SIMPLE;

      countryPageMap.set(c.code, {
        cover: coverPage,
        qtd: coverPage + qtdOffset,
        ytd: coverPage + ytdOffset,
      });

      currentPage += slidesPerCountry;
    });

    const countryItems = TOC_COUNTRY_CODES.map((code) => {
      const c = EXPORT_COUNTRIES.find((ec) => ec.code === code);
      const pages = countryPageMap.get(code);
      if (!c || !pages) return null;

      const subItems: TocSubItem[] = [
        {
          label: qtdLabel,
          page: pages.qtd,
          slideId: getCountrySlideId(c.code, 'qtd-abi'),
        },
        {
          label: ytdLabel,
          page: pages.ytd,
          slideId: getCountrySlideId(c.code, 'ytd-abi'),
        },
      ];

      return {
        title: c.name,
        page: pages.cover,
        slideId: getCountrySlideId(c.code, 'cover'),
        countryCode: c.code,
        countryName: c.name,
        countryImageUrl: `${assetHost}/countries/rounded_flags/${c.code}.png`,
        subItems,
      };
    }).filter(Boolean) as TocItem[];

    const gridGroup: TocGroup = {
      layout: 'grid',
      columns: PAGE_LAYOUT.TOC_GRID_COLUMNS,
      items: countryItems,
    };

    return [stackedGroup, gridGroup];
  }, [quarterYearFull, fiscalYear, assetHost]);
};
